package vn.edu.huy.controller;

import javax.servlet.*;import javax.servlet.http.*;import java.io.*;import vn.edu.huy.model.*;import vn.edu.huy.util.*;import vn.edu.huy.service.impl.*;
public class VideoController_24162049 extends HttpServlet {
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!r.getServletPath().equals("/video/detail")){s.sendError(405);return;}Video_24162049 v=new VideoServiceImpl_24162049().detail(Web_24162049.param(r,"id"),true);if(v==null){s.sendError(404);return;}r.setAttribute("video",v);User_24162049 u=Web_24162049.current(r);r.setAttribute("liked",u!=null&&new FavoriteServiceImpl_24162049().exists(u.getUsername(),v.getVideoId()));Web_24162049.view(r,s,"video");}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String path=r.getServletPath();if(path.equals("/video/detail")){s.sendError(405);return;}String id=Web_24162049.param(r,"id");String user=Web_24162049.current(r).getUsername();try{if(path.equals("/video/like")){new FavoriteServiceImpl_24162049().set(user,id,"true".equals(r.getParameter("liked")));Web_24162049.flash(r,"Đã cập nhật danh sách yêu thích.");}else {synchronized(r.getSession()){Long last=(Long)r.getSession().getAttribute("lastShare");if(last!=null&&System.currentTimeMillis()-last<30000)throw new IllegalArgumentException("Vui lòng chờ 30 giây trước khi chia sẻ tiếp.");new ShareServiceImpl_24162049().share(user,id,Web_24162049.param(r,"email"));r.getSession().setAttribute("lastShare",System.currentTimeMillis());}Web_24162049.flash(r,"Đã gửi email chia sẻ video thành công.");}}catch(IllegalArgumentException e){Web_24162049.flash(r,e.getMessage());}Web_24162049.redirect(r,s,"/video/detail?id="+Web_24162049.encode(id));}
}
